#include <iostream>
#include <vector>
using namespace std;

int getAnswer(int n) {
    if (n == 1) {
        return 1;
    }

    vector<int> pure_nums;
    int x = 2;

    // 求前 n-1 个纯净数
    while ((int)pure_nums.size() < n - 1) {
        bool ok = true;
        for (int i = 2; i * i <= x; i++) {
            if (x % i == 0) {
                ok = false;
                break;
            }
        }
        if (ok) {
            pure_nums.push_back(x);
        }
        x++;
    }

    vector<int> steps;
    int prev = 0;
    for (int p : pure_nums) {
        steps.push_back(p - prev);
        prev = p;
    }

    int f = 0;
    for (int m = 2; m <= n; m++) {
        f = (f + steps[n - m]) % m;
    }

    return f + 1;
}

